_SOURCES = json.loads('{"__init__":"\\"\\"\\"Truco Cu\\u00e1ntico: original hackathon implementation, October 2026.\\"\\"\\"\\n","gates":"\\"\\"\\"Fixed rotation catalogue shared by the deck and Qiskit circuit builder.\\"\\"\\"\\nimport math\\nANGLES = {\'pi/2\': math.pi/2, \'pi/6\': math.pi/6, \'-pi/6\': -math.pi/6,\\n          \'pi/3\': math.pi/3, \'pi/67\': math.pi/67}\\nROTATIONS = {f\'{axis}:{name}\': (axis.lower(), angle)\\n             for axis in (\'RX\', \'RY\', \'RZ\') for name, angle in ANGLES.items()}\\n# Compatibility aliases for saved circuits; the new deck uses explicit angles.\\nROTATIONS.update({\'RY+\': (\'ry\', math.pi/6), \'RY-\': (\'ry\', -math.pi/6)})\\nVALID = (\'H\', \'X\', \'Z\', *ROTATIONS)\\nDECK = (\'H\',)*6 + (\'X\',) + (\'Z\',)*3 + tuple(g for g in ROTATIONS if \':\' in g)*2\\n","classic":"\\"\\"\\"Pure rules for the specified two-player, no-Flor variant.\\"\\"\\"\\nfrom dataclasses import dataclass\\nfrom itertools import combinations\\nfrom .gates import DECK as GATES\\n\\nNUMBERS = (1, 2, 3, 4, 5, 6, 7, 10, 11, 12)\\nSUITS = (\'espada\', \'basto\', \'oro\', \'copa\')\\nLINK = {\'espada\': \'copa\', \'copa\': \'espada\', \'basto\': \'oro\', \'oro\': \'basto\'}\\n\\n@dataclass(frozen=True)\\nclass Card:\\n    number: int\\n    suit: str\\n    def __post_init__(self):\\n        if self.number not in NUMBERS or self.suit not in SUITS:\\n            raise ValueError(\'Carta inv\\u00e1lida\')\\n    def linked(self):\\n        return Card(self.number, LINK[self.suit])\\n    def data(self):\\n        return {\'number\': self.number, \'suit\': self.suit, \'label\': f\'{self.number} de {self.suit}\'}\\n\\nDECK = tuple(Card(n, s) for n in NUMBERS for s in SUITS)\\nPAIRS = tuple((Card(n, s), Card(n, s).linked()) for n in NUMBERS for s in (\'espada\', \'basto\'))\\nSPECIAL = {(1, \'espada\'): 14, (1, \'basto\'): 13, (7, \'espada\'): 12, (7, \'oro\'): 11}\\nRANK = {3: 10, 2: 9, 1: 8, 12: 7, 11: 6, 10: 5, 7: 4, 6: 3, 5: 2, 4: 1}\\n\\ndef strength(card):\\n    return SPECIAL.get((card.number, card.suit), RANK[card.number])\\n\\ndef deal(rng):\\n    cards = [rng.choice(pair) for pair in rng.sample(PAIRS, 6)]\\n    rng.shuffle(cards)\\n    return [cards[:3], cards[3:]]\\n\\ndef envido(cards):\\n    value = lambda c: c.number if c.number <= 7 else 0\\n    same = [20 + value(a) + value(b) for a, b in combinations(cards, 2) if a.suit == b.suit]\\n    return max(same) if same else max(map(value, cards))\\n\\ndef hand_winner(bazas, mano):\\n    \\"\\"\\"None means undecided. -1 marks a parda; players are 0 and 1.\\"\\"\\"\\n    if not bazas:\\n        return None\\n    if len(bazas) >= 2:\\n        first, second = bazas[:2]\\n        if first == -1 and second != -1:\\n            return second\\n        if first != -1 and (second == first or second == -1):\\n            return first\\n    if len(bazas) == 3:\\n        first, second, third = bazas\\n        if third != -1:\\n            return third\\n        return next((p for p in (first, second) if p != -1), mano)\\n    return None\\n\\nENVIDO_CHAINS = {\\n    (): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\',): (\'envido\', \'real\', \'falta\'),\\n    (\'envido\', \'envido\'): (\'real\', \'falta\'),\\n    (\'real\',): (\'falta\',),\\n    (\'envido\', \'real\'): (\'falta\',),\\n    (\'envido\', \'envido\', \'real\'): (\'falta\',),\\n}\\n\\ndef envido_value(chain, scores=None, loser=None):\\n    if chain[-1] == \'falta\':\\n        if scores is None:\\n            raise ValueError(\'Falta necesita el marcador\')\\n        return 15 - max(scores)\\n    return sum({\'envido\': 2, \'real\': 3}[c] for c in chain)\\n\\ndef refusal_value(chain):\\n    return envido_value(chain[:-1]) if len(chain) > 1 else 1\\n\\n\\n\\nclass GateDeck:\\n    def __init__(self, rng):\\n        self.rng = rng\\n        self.draw_pile = list(GATES)\\n        self.discard = []\\n        rng.shuffle(self.draw_pile)\\n    def draw_hand(self):\\n        if len(self.draw_pile) < 8:\\n            self.draw_pile.extend(self.discard)\\n            self.discard.clear()\\n            self.rng.shuffle(self.draw_pile)\\n        return [[self.draw_pile.pop() for _ in range(4)] for _ in range(2)]\\n    def discard_hand(self, hands):\\n        self.discard.extend(g for hand in hands for g in hand)\\n","quantum":"\\"\\"\\"Qiskit previews and explicit measurement sources. No game scoring here.\\"\\"\\"\\nimport math\\nimport random\\nfrom dataclasses import dataclass, field\\nfrom qiskit import QuantumCircuit\\nfrom qiskit.quantum_info import Statevector, DensityMatrix, Operator, Kraus\\nimport numpy as np\\n\\nfrom .gates import VALID, ROTATIONS\\n\\n# Educational seconds, deliberately not an IonQ device calibration.\\nNOISE_T1 = 60.0\\nNOISE_TPHI = 90.0\\nNOISE_T2 = 1 / (1 / (2 * NOISE_T1) + 1 / NOISE_TPHI)\\n\\ndef noisy_state(gates, seconds):\\n    if type(seconds) not in (int, float) or not math.isfinite(seconds) or seconds < 0:\\n        raise ValueError(\'Tiempo de ruido inv\\u00e1lido\')\\n    state = DensityMatrix.from_instruction(circuit(gates))\\n    gamma = -math.expm1(-seconds / NOISE_T1)\\n    amplitude = Kraus([np.diag([1, math.sqrt(1-gamma)]),\\n                       np.array([[0, math.sqrt(gamma)], [0, 0]])])\\n    # A random Z with probability p attenuates coherence by 1-2p.\\n    p = -math.expm1(-seconds / NOISE_TPHI) / 2\\n    dephasing = Kraus([math.sqrt(1-p)*np.eye(2), math.sqrt(p)*np.diag([1,-1])])\\n    return state.evolve(amplitude).evolve(dephasing)\\n\\ndef noise_view(gates, seconds, ideal=None):\\n    data = dict(ideal or preview(gates))\\n    state = noisy_state(gates, seconds)\\n    matrix = state.data\\n    vector = [float(2*matrix[0,1].real), float(-2*matrix[0,1].imag),\\n              float((matrix[0,0]-matrix[1,1]).real)]\\n    x,y,z = data[\'steps\'][-1][\'bloch\']\\n    path = []\\n    for i in range(25):\\n        t = seconds*i/24\\n        path.append([x*math.exp(-t/NOISE_T2), y*math.exp(-t/NOISE_T2),\\n                     1+(z-1)*math.exp(-t/NOISE_T1)])\\n    data.update(probabilities=[float(p) for p in state.probabilities()], bloch=vector,\\n                density_matrix=[[[float(v.real),float(v.imag)] for v in row] for row in matrix],\\n                purity=float(state.purity().real), amplitudes=None, relative_phase=None,\\n                noise_trajectory=path,\\n                noise={\'seconds\':seconds,\'t1\':NOISE_T1,\'tphi\':NOISE_TPHI,\'t2\':NOISE_T2,\\n                       \'model\':\'amplitude damping + dephasing; educational time scale\',\\n                       \'ideal_probabilities\':data[\'steps\'][-1][\'probabilities\']})\\n    return data\\n\\ndef circuit(gates, measured=False):\\n    if not isinstance(gates, (list, tuple)) or len(gates) > 3 or any(g not in VALID for g in gates):\\n        raise ValueError(\'Circuito inv\\u00e1lido: hasta tres compuertas\')\\n    qc = QuantumCircuit(1, 1) if measured else QuantumCircuit(1)\\n    for gate in gates:\\n        if gate == \'H\': qc.h(0)\\n        elif gate == \'X\': qc.x(0)\\n        elif gate == \'Z\': qc.z(0)\\n        else:\\n            axis, angle = ROTATIONS[gate]\\n            getattr(qc, axis)(angle, 0)\\n    if measured: qc.measure(0, 0)\\n    return qc\\n\\ndef preview(gates):\\n    steps = []\\n    for i in range(len(gates) + 1):\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        a, b = state.data\\n        cross = a.conjugate() * b\\n        phase = None if abs(a) < 1e-12 or abs(b) < 1e-12 else float(math.atan2(cross.imag, cross.real))\\n        steps.append({\'gate\': gates[i-1] if i else \'|0\\u27e9\',\\n                      \'amplitudes\': [[float(z.real), float(z.imag)] for z in (a, b)],\\n                      \'probabilities\': [float(p) for p in state.probabilities()],\\n                      \'bloch\': [float(2 * cross.real), float(2 * cross.imag), float(abs(a)**2 - abs(b)**2)],\\n                      \'relative_phase\': phase})\\n    # Partial rotations for a physically consistent Bloch trajectory.\\n    # H is a pi rotation around (X+Z)/sqrt(2), equivalent up to global phase.\\n    trajectory = [steps[0][\'bloch\']]\\n    segments = []\\n    for i, gate in enumerate(gates):\\n        start = len(trajectory) - 1\\n        state = Statevector.from_instruction(circuit(gates[:i]))\\n        axis, angle = ROTATIONS.get(gate, (None, math.pi))\\n        for t in range(1, 25):\\n            theta = angle * t / 24\\n            partial = QuantumCircuit(1)\\n            if axis: getattr(partial, axis)(theta, 0)\\n            elif gate == \'X\': partial.rx(theta, 0)\\n            elif gate == \'Z\': partial.rz(theta, 0)\\n            else:\\n                h = np.array([[1,1],[1,-1]]) / math.sqrt(2)\\n                partial.unitary(Operator(math.cos(theta/2)*np.eye(2)-1j*math.sin(theta/2)*h), [0])\\n            a, b = state.evolve(partial).data\\n            cross = a.conjugate()*b\\n            trajectory.append([float(2*cross.real),float(2*cross.imag),float(abs(a)**2-abs(b)**2)])\\n        segments.append({\'gate\':gate, \'start\':start, \'end\':len(trajectory)-1})\\n    return {\'gates\': list(gates), \'steps\': steps, \'trajectory\':trajectory, \'segments\':segments, **steps[-1]}\\n\\n@dataclass\\nclass QuantumCard:\\n    index: int\\n    tokens: list\\n    sequence: list = field(default_factory=list)\\n    locked: bool = False\\n    result: int | None = None\\n    record: dict | None = None\\n    noise_enabled: bool = False\\n    noise_seconds: float = 0.0\\n    _preview: dict | None = field(default=None, repr=False)\\n    def edit(self, indices):\\n        if self.locked: raise ValueError(\'Circuito confirmado: no puede cambiar\')\\n        if not isinstance(indices, (list, tuple)) or len(indices) > 3 or any(type(i) is not int or not 0 <= i < len(self.tokens) for i in indices) or len(set(indices)) != len(indices):\\n            raise ValueError(\'Cada ficha se usa una vez; m\\u00e1ximo tres\')\\n        self.sequence = list(indices)\\n        self._preview = None\\n        return self.view()\\n    @property\\n    def gates(self):\\n        return [self.tokens[i] for i in self.sequence]\\n    def view(self):\\n        if self._preview is None: self._preview = preview(self.gates)\\n        return noise_view(self.gates, self.noise_seconds, self._preview) if self.noise_enabled else self._preview\\n    def age(self, seconds):\\n        if type(seconds) not in (int,float) or not math.isfinite(seconds) or not 0 <= seconds <= 5:\\n            raise ValueError(\'Intervalo de ruido inv\\u00e1lido\')\\n        if self.noise_enabled and self.locked and self.result is None:\\n            self.noise_seconds += seconds\\n    def collapse(self, bit, record):\\n        if not self.locked: raise ValueError(\'Confirm\\u00e1 antes de medir\')\\n        if self.result is not None: raise ValueError(\'La carta ya fue medida\')\\n        if type(bit) is not int or bit not in (0, 1): raise ValueError(\'Resultado inv\\u00e1lido\')\\n        self.result, self.record = bit, record\\n\\nclass LocalSampler:\\n    name = \'LOCAL DEVELOPMENT \\u2014 Qiskit Statevector; NO IonQ\'\\n    def sample(self, gates, noise_seconds=None):\\n        state = Statevector.from_instruction(circuit(gates)) if noise_seconds is None else noisy_state(gates, noise_seconds)\\n        bit = int(state.sample_memory(1)[0])\\n        return bit, {\'backend\': self.name if noise_seconds is None else \'LOCAL DEVELOPMENT \\u2014 Qiskit DensityMatrix; NO IonQ\', \'shots\': 1, \'gates\': list(gates), \'result\': bit,\\n                     \'method\': \'Qiskit Statevector.sample_memory(1)\' if noise_seconds is None else \'Qiskit DensityMatrix.sample_memory(1)\',\\n                     **({\'noise\':{\'seconds\':noise_seconds,\'t1\':NOISE_T1,\'tphi\':NOISE_TPHI,\'t2\':NOISE_T2,\\n                                  \'probabilities\':[float(p) for p in state.probabilities()]}} if noise_seconds is not None else {})}\\n\\ndef effective_sample(distribution, rng=None):\\n    \\"\\"\\"One effective draw from validated one-qubit probabilities/counts.\\"\\"\\"\\n    weights = [0.0, 0.0]\\n    for key, value in distribution.items():\\n        key = str(key).replace(\' \', \'\')\\n        if key in (\'0\', \'0x0\'): bit = 0\\n        elif key in (\'1\', \'0x1\'): bit = 1\\n        else: raise ValueError(\'Orden/formato de bits no reconocido: se esperaba un bit\')\\n        value = float(value)\\n        if not math.isfinite(value) or value < 0: raise ValueError(\'Distribuci\\u00f3n inv\\u00e1lida\')\\n        weights[bit] += value\\n    total = sum(weights)\\n    if not total or not math.isfinite(total): raise ValueError(\'Resultado sin probabilidades v\\u00e1lidas\')\\n    return int((rng or random.SystemRandom()).random() >= weights[0] / total)\\n","remote":"\\"\\"\\"Adapter for Qollab\'s documented injected Qiskit backend.\\n\\nNo credentials, provider construction or undocumented network endpoints.\\nLifecycle is polled by the UI so it stays responsive. Never substitutes local data.\\n\\"\\"\\"\\nimport time\\nfrom qiskit.providers.jobstatus import JobStatus\\nfrom .quantum import circuit, effective_sample\\n\\nclass RemoteMeasurement:\\n    def __init__(self, backend, one_job=True):\\n        self.backend = backend\\n        self.one_job = one_job\\n        self.sent = False\\n        self.job = None\\n        self.gates = []\\n        self.cached = None\\n        self.started = None\\n        self.last_error = None\\n        self.submission_uncertain = False\\n    def info(self):\\n        name = getattr(self.backend,\'name\',\'unknown\')\\n        if callable(name): name = name()\\n        config = self.backend.configuration() if hasattr(self.backend,\'configuration\') else None\\n        simulator = getattr(config,\'simulator\',None) if config else None\\n        module = type(self.backend).__module__\\n        return {\'name\':str(name),\'module\':module,\'simulator\':simulator,\\n                \'noise_model\':str(getattr(getattr(self.backend,\'options\',None),\'noise_model\',None))}\\n    def start(self, sequences):\\n        if self.job is not None: return  # resumes the SAME job after timeout\\n        if self.submission_uncertain:\\n            raise RuntimeError(\'El env\\u00edo anterior tiene estado incierto. No se enviar\\u00e1 otro job que pueda duplicar la medici\\u00f3n\')\\n        info = self.info()\\n        if \'ionq\' not in (info[\'name\']+\' \'+info[\'module\']).lower():\\n            raise ValueError(\'Seleccion\\u00e1 un simulador IonQ; este backend no est\\u00e1 identificado como IonQ\')\\n        if info[\'simulator\'] is not True and \'simulator\' not in info[\'name\'].lower():\\n            raise ValueError(\'No se verific\\u00f3 que el backend sea simulador. No se enviar\\u00e1 a hardware\')\\n        if self.sent and self.one_job:\\n            raise ValueError(\'Qollab permite un solo job IonQ por ejecuci\\u00f3n. No se inventar\\u00e1 una segunda medici\\u00f3n\')\\n        if not sequences: raise ValueError(\'No hay circuitos para medir\')\\n        circuits = [circuit(g, measured=True) for g in sequences]\\n        self.gates = [list(g) for g in sequences]\\n        self.sent = True  # fail closed after uncertain submission; avoid duplicate jobs\\n        self.started = time.monotonic()\\n        try:\\n            self.job = self.backend.run(circuits if len(circuits)>1 else circuits[0], shots=1)\\n        except Exception as exc:\\n            self.submission_uncertain = True\\n            message = str(exc).lower()\\n            recognized = next((p for p in (\'only one\',\'one job\',\'xhr\',\'xmlhttprequest\',\'keyword\',\'connection\',\'not supported\',\'unexpected\') if p in message), \'unclassified\')\\n            self.last_error = {\'type\':type(exc).__name__,\'recognized\':recognized}\\n            raise RuntimeError(f\'Fall\\u00f3 el env\\u00edo ({type(exc).__name__}; {recognized}); estado remoto incierto. No se reenviar\\u00e1 autom\\u00e1ticamente\') from None\\n    def poll(self):\\n        if self.cached is not None: return {\'done\':True,\'measurements\':self.cached}\\n        if self.job is None: raise ValueError(\'No hay job remoto para consultar\')\\n        status = self.job.status()\\n        if status in (JobStatus.ERROR,JobStatus.CANCELLED):\\n            self.last_error = str(status)\\n            raise RuntimeError(\'IonQ inform\\u00f3 error o cancelaci\\u00f3n; no hay resultado de juego\')\\n        if status != JobStatus.DONE:\\n            if time.monotonic()-self.started>120:\\n                raise TimeoutError(\'IonQ sigue pendiente. Reintentar consulta retoma el mismo job\')\\n            return {\'done\':False,\'status\':str(status)}\\n        try:\\n            result = self.job.result()\\n            measurements = []\\n            for i, gates in enumerate(self.gates):\\n                # A single bit: only 0/1 or 0x0/0x1 allowed. No low-probability filtering.\\n                counts = result.get_counts(i)\\n                bit = effective_sample(counts)\\n                job_id = str(self.job.job_id()) if hasattr(self.job,\'job_id\') else None\\n                record = {\'backend\':self.info(),\'shots\':1,\'gates\':gates,\'result\':bit,\\n                          \'job_id\':job_id,\'distribution\':dict(counts),\\n                          \'method\':\'one effective sample from returned counts/probabilities\'}\\n                measurements.append((bit,record))\\n            self.cached = measurements\\n            return {\'done\':True,\'measurements\':measurements}\\n        except Exception as exc:\\n            self.last_error = type(exc).__name__\\n            raise RuntimeError(\'No se pudo validar el resultado IonQ; no se asign\\u00f3 una identidad\') from None\\n    def release(self):\\n        self.job = None; self.cached = None; self.started = None\\n","game":"\\"\\"\\"Interface-independent state machine. Private projections are explicit.\\"\\"\\"\\nimport random\\nfrom datetime import datetime, timezone\\nfrom .classic import Card, deal, strength, envido, hand_winner, ENVIDO_CHAINS, envido_value, refusal_value, GateDeck\\nfrom .quantum import QuantumCard\\n\\nLABELS = {\'envido\':\'Envido\', \'real\':\'Real Envido\', \'falta\':\'Falta Envido\',\\n          \'truco\':\'Truco\', \'retruco\':\'Retruco\', \'vale4\':\'Vale Cuatro\',\\n          \'accept\':\'Quiero\', \'reject\':\'No quiero\', \'fold\':\'Irse al mazo\',\\n          \'reassert\':\'Reafirmar canto\', \'confirm\':\'Confirmar circuito\',\\n          \'next\':\'Nueva mano\'}\\n\\nclass Game:\\n    def __init__(self, names, rng=None, privacy=False, noise=False, quantum=True, deals=None, mano=None):\\n        if not isinstance(names, (list, tuple)) or len(names) != 2 or any(not isinstance(n,str) or not n.strip() or len(n)>30 for n in names):\\n            raise ValueError(\'Ingres\\u00e1 dos nombres de hasta 30 caracteres\')\\n        self.names = [n.strip() for n in names]\\n        if type(privacy) is not bool: raise ValueError(\\"Privacidad inv\\u00e1lida\\")\\n        self.privacy = privacy\\n        if type(noise) is not bool: raise ValueError(\'Ruido inv\\u00e1lido\')\\n        self.noise = noise\\n        # quantum=False plays classic Truco: no preparation phase and no measurements.\\n        if type(quantum) is not bool: raise ValueError(\'Modo cu\\u00e1ntico inv\\u00e1lido\')\\n        self.quantum = quantum\\n        self.deals = [self.validate_deal(d) for d in deals or []]\\n        self.rng = rng or random.SystemRandom()\\n        self.scores = [0,0]\\n        self.mano = self.rng.randrange(2) if mano is None else mano\\n        if self.mano not in (0,1): raise ValueError(\'Mano inv\\u00e1lida\')\\n        self.gate_deck = GateDeck(self.rng)\\n        self.history = []\\n        self.hand_number = 0\\n        self.new_hand()\\n    def new_hand(self):\\n        self.hand_number += 1\\n        # Scripted deals (tutorial) are used first; afterwards the deal is random.\\n        self.cards = self.deals.pop(0) if self.deals else deal(self.rng)\\n        self.tokens = self.gate_deck.draw_hand() if self.quantum else [[],[]]\\n        self.q = [None, None]\\n        self.played = [set(), set()]\\n        self.table = []\\n        self.bazas = []\\n        self.events = []\\n        self.actor = self.mano\\n        self.turn = self.mano\\n        self.phase = \'prepare\' if self.quantum else \'play\'\\n        self.stake = 1\\n        self.truco_right = None\\n        self.pending = None\\n        self.suspended = None\\n        self.envido_done = False\\n        self.envido_result = None\\n        self.measure_context = None\\n        self.measure_requests = []\\n        self.last_public_measurement = None\\n        self.winner = None\\n        self.event(\'Reparto de mano\', mano=self.mano)\\n    @staticmethod\\n    def validate_deal(hands):\\n        if not isinstance(hands,(list,tuple)) or len(hands) != 2 or any(not isinstance(h,(list,tuple)) or len(h) != 3 for h in hands):\\n            raise ValueError(\'Reparto inv\\u00e1lido: tres cartas por jugador\')\\n        cards = [[c if isinstance(c,Card) else Card(*c) for c in hand] for hand in hands]\\n        if len({c for hand in cards for c in hand}) != 6: raise ValueError(\'Reparto inv\\u00e1lido: cartas repetidas\')\\n        return cards\\n    def event(self, text, **data):\\n        self.events.append({\'text\':text, \'time\':datetime.now(timezone.utc).isoformat(), **data})\\n    def effective_card(self, player, index):\\n        card = self.cards[player][index]\\n        q = self.q[player]\\n        return card.linked() if q is not None and q.index == index and q.result == 1 else card\\n    def can_envido(self):\\n        return not self.envido_done and not self.bazas and self.stake == 1 and not self.played[self.actor]\\n    def legal(self):\\n        if self.phase == \'prepare\': return [\'choose\',\'edit\',\'confirm\']\\n        if self.phase == \'play\':\\n            result = [\'play\',\'fold\']\\n            if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            if self.stake < 4 and (self.stake == 1 or self.truco_right == self.actor):\\n                result += [{1:\'truco\',2:\'retruco\',3:\'vale4\'}[self.stake]]\\n            return result\\n        if self.phase == \'respond\':\\n            result = [\'accept\',\'reject\']\\n            if self.pending[\'kind\'] == \'envido\':\\n                result += list(ENVIDO_CHAINS.get(tuple(self.pending[\'chain\']), ()))\\n            else:\\n                if self.pending[\'level\'] < 4:\\n                    result += [{2:\'retruco\',3:\'vale4\'}[self.pending[\'level\']]]\\n                if self.can_envido(): result += list(ENVIDO_CHAINS[()])\\n            return result\\n        if self.phase == \'reassert\': return [\'reassert\']\\n        if self.phase == \'hand_end\': return [\'next\']\\n        return []\\n    def dispatch(self, action, value=None):\\n        if action not in self.legal(): raise ValueError(\'Acci\\u00f3n inv\\u00e1lida para este estado\')\\n        p = self.actor\\n        if action == \'choose\':\\n            if type(value) is not int or not 0 <= value < 3: raise ValueError(\'Carta inv\\u00e1lida\')\\n            self.q[p] = QuantumCard(value, self.tokens[p], noise_enabled=self.noise)\\n        elif action == \'edit\':\\n            if self.q[p] is None: raise ValueError(\'Eleg\\u00ed una carta\')\\n            self.q[p].edit(value)\\n        elif action == \'confirm\':\\n            if self.q[p] is None: raise ValueError(\'Eleg\\u00ed exactamente una carta\')\\n            self.q[p].locked = True\\n            other = 1-p\\n            if self.q[other] is None or not self.q[other].locked:\\n                self.actor = other\\n            else:\\n                self.phase = \'play\'; self.actor = self.turn = self.mano\\n        elif action in (\'envido\',\'real\',\'falta\'):\\n            if self.phase == \'respond\' and self.pending[\'kind\'] == \'envido\':\\n                chain = self.pending[\'chain\'] + [action]\\n            else:\\n                if self.phase == \'respond\': self.suspended = self.pending.copy()\\n                chain = [action]\\n            self.pending = {\'kind\':\'envido\',\'chain\':chain,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(\' \\u2192 \'.join(LABELS[c] for c in chain), player=p, kind=\'speech\', speech=action)\\n        elif action in (\'truco\',\'retruco\',\'vale4\'):\\n            level = {\'truco\':2, \'retruco\':3,\'vale4\':4}[action]\\n            # Raising a pending canto accepts its prior level implicitly.\\n            if self.phase == \'respond\': self.stake = self.pending[\'level\']\\n            self.pending = {\'kind\':\'truco\',\'level\':level,\'proposer\':p}\\n            self.phase = \'respond\'; self.actor = 1-p\\n            self.event(LABELS[action], player=p, kind=\'speech\', speech=action)\\n        elif action == \'reject\':\\n            self.event(\'No quiero\', player=p, kind=\'speech\', speech=\'reject\')\\n            pending = self.pending\\n            if pending[\'kind\'] == \'envido\':\\n                self.envido_done = True\\n                self.award(pending[\'proposer\'], refusal_value(pending[\'chain\']), \'Envido no querido\')\\n                self.pending = None\\n                if self.phase != \'match_end\': self.resume_truco()\\n            else:\\n                self.finish_hand(pending[\'proposer\'], pending[\'level\']-1, \'Truco no querido\')\\n        elif action == \'accept\':\\n            self.event(\'Quiero\', player=p, kind=\'speech\', speech=\'accept\')\\n            if self.pending[\'kind\'] == \'truco\':\\n                self.stake = self.pending[\'level\']; self.truco_right = p\\n                self.pending = None; self.phase = \'play\'; self.actor = self.turn\\n            else:\\n                self.envido_done = True\\n                self.envido_acceptor = p\\n                self.begin_measure(\'envido\', [self.mano,1-self.mano])\\n        elif action == \'reassert\':\\n            self.pending = self.suspended; self.suspended = None\\n            self.event(\'Truco reafirmado\', player=p, kind=\'speech\', speech=\'truco\')\\n            self.phase = \'respond\'; self.actor = 1-p\\n        elif action == \'play\':\\n            if type(value) is not int or not 0 <= value < 3 or value in self.played[p]:\\n                raise ValueError(\'Carta no disponible\')\\n            q = self.q[p]\\n            if q is not None and q.index == value and q.result is None:\\n                self.play_intent = (p, value)\\n                self.begin_measure(\'play\', [p])\\n            else: self.commit_play(p, value)\\n        elif action == \'fold\':\\n            self.event(\'Al mazo\', player=p, kind=\'speech\', speech=\'fold\')\\n            self.finish_hand(1-p, self.stake, \'Al mazo\')\\n        elif action == \'next\':\\n            self.mano = 1-self.mano\\n            self.new_hand()\\n    def begin_measure(self, context, players):\\n        self.measure_context = context\\n        self.measure_requests = [p for p in players if self.q[p] is not None and self.q[p].result is None]\\n        self.phase = \'measure\'\\n        if not self.measure_requests: self.after_measure()\\n    def complete_measure(self, measurements):\\n        if self.phase != \'measure\' or not isinstance(measurements, (list, tuple)) or len(measurements) != len(self.measure_requests):\\n            raise ValueError(\'No hay medici\\u00f3n pendiente o lote incompleto\')\\n        if any(not isinstance(item, (list, tuple)) or len(item) != 2 or\\n               type(item[0]) is not int or item[0] not in (0,1) or not isinstance(item[1], dict)\\n               for item in measurements):\\n            raise ValueError(\'Medici\\u00f3n inv\\u00e1lida\')\\n        # Validate the whole batch before collapsing any card.\\n        if any(not self.q[p].locked or self.q[p].result is not None for p in self.measure_requests):\\n            raise ValueError(\'La carta no est\\u00e1 disponible para medir\')\\n        for p, (bit, record) in zip(self.measure_requests, measurements):\\n            self.q[p].collapse(bit, {**record,\'moment\':self.measure_context})\\n        self.measure_requests = []\\n        self.after_measure()\\n    def after_measure(self):\\n        if self.measure_context == \'envido\':\\n            self.resolve_envido()\\n        else:\\n            p, index = self.play_intent\\n            self.last_public_measurement = {\'player\':p, **self.quantum_report(p)}\\n            public = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\')}\\n            self.event(\'Carta medida\', kind=\'measurement\', measurement=public)\\n            self.commit_play(p, index)\\n    def resolve_envido(self):\\n        values = [envido([self.effective_card(p,i) for i in range(3)]) for p in (0,1)]\\n        winner = self.mano if values[0] == values[1] else int(values[1] > values[0])\\n        points = envido_value(self.pending[\'chain\'], self.scores, 1-winner)\\n        self.envido_result = {\'values\':values,\'winner\':winner,\'points\':points}\\n        first = self.envido_acceptor\\n        self.event(\'Tantos de Envido\', kind=\'speech\', speech=\'envido_first\', player=first, value=values[first])\\n        other = 1-first\\n        self.event(\'Respuesta de tantos\', kind=\'speech\', speech=\'envido_answer\', player=other, value=values[other], better=values[other]>values[first], tie=values[other]==values[first], mano=other==self.mano)\\n        self.award(winner, points, \'Envido querido\', values=values)\\n        self.pending = None\\n        if self.phase != \'match_end\': self.resume_truco()\\n    def resume_truco(self):\\n        if self.suspended:\\n            self.phase = \'reassert\'; self.actor = self.suspended[\'proposer\']\\n        else:\\n            self.phase = \'play\'; self.actor = self.turn\\n    def commit_play(self, p, index):\\n        card = self.effective_card(p,index)\\n        self.played[p].add(index)\\n        self.table.append({\'player\':p,\'card\':card.data()})\\n        self.event(\'Carta jugada\', player=p, card=card.data())\\n        if len(self.table) % 2:\\n            self.turn = self.actor = 1-p; self.phase = \'play\'; return\\n        pair = self.table[-2:]\\n        ranks = [strength(Card(item[\'card\'][\'number\'], item[\'card\'][\'suit\'])) for item in pair]\\n        winner = -1 if ranks[0] == ranks[1] else pair[int(ranks[1] > ranks[0])][\'player\']\\n        self.bazas.append(winner)\\n        self.event(\'Baza parda\' if winner == -1 else \'Baza ganada\', winner=winner,\\n                   cards=list(pair), strengths=ranks)\\n        outcome = hand_winner(self.bazas,self.mano)\\n        if outcome is not None: self.finish_hand(outcome,self.stake,\'Mano ganada\')\\n        else:\\n            self.turn = self.actor = pair[0][\'player\'] if winner == -1 else winner\\n            self.phase = \'play\'\\n    def award(self, player, points, reason, **data):\\n        before = self.scores[player]\\n        self.scores[player] = min(15,self.scores[player]+points)\\n        self.event(reason, winner=player, points=points, gained=self.scores[player]-before, **data)\\n        if self.scores[player] == 15:\\n            self.winner = player; self.phase = \'match_end\'\\n            self.archive()\\n    def finish_hand(self, winner, points, reason):\\n        self.award(winner,points,reason)\\n        if self.phase != \'match_end\':\\n            self.winner = winner; self.archive()\\n            self.phase = \'hand_end\'\\n    def archive(self):\\n        if self.history and self.history[-1][\'hand\'] == self.hand_number: return\\n        self.history.append({\'hand\':self.hand_number,\'mano\':self.mano,\'scores\':list(self.scores),\\n                             \'quantum\':[self.quantum_report(p) for p in (0,1)],\\n                             \'cards\':[[{\'original\':self.cards[p][i].data(), \'effective\':self.effective_card(p,i).data(),\\n                                        \'played\':i in self.played[p], \'quantum\':self.q[p] is not None and self.q[p].index==i}\\n                                       for i in range(3)] for p in (0,1)],\\n                             \'events\':list(self.events),\'bazas\':list(self.bazas)})\\n        self.gate_deck.discard_hand(self.tokens)\\n    def quantum_report(self,p):\\n        q = self.q[p]\\n        if q is None: return None\\n        original = self.cards[p][q.index]\\n        return {\'original\':original.data(), \'linked\':original.linked().data(),\\n                \'tokens\':list(q.tokens),\'sequence\':list(q.sequence), \'preview\':q.view(),\\n                \'result\':q.result,\'record\':q.record,\'locked\':q.locked,\\n                \'discarded\':[g for i,g in enumerate(q.tokens) if i not in q.sequence],\\n                \'explanation\': \'Termin\\u00f3 sin producir un resultado cl\\u00e1sico.\' if q.result is None else\\n                f\'La medici\\u00f3n produjo {q.result}. La identidad permanece fija durante la mano.\'}\\n    def public_view(self):\\n        data = {\'names\':self.names,\'scores\':self.scores,\'mano\':self.mano,\'actor\':self.actor,\\n                \'phase\':self.phase,\'hand\':self.hand_number,\'stake\':self.stake,\\n                \'bazas\':self.bazas,\'table\':self.table,\'pending\':self.pending,\\n                \'envido\':self.envido_result,\'events\':self.events,\\n                \'actions\':[{\'id\':a,\'label\':LABELS.get(a,a),\'hint\':self.action_hint(a)} for a in self.legal() if a not in (\'choose\',\'edit\',\'play\')],\\n                \'winner\':self.winner, \'privacy\':self.privacy, \'noise\':self.noise, \'quantum\':self.quantum}\\n        if self.last_public_measurement and self.phase != \'measure\':\\n            # The explicit public-play exception discloses circuit and preview, never tokens.\\n            data[\'public_measurement\'] = {k:v for k,v in self.last_public_measurement.items() if k in (\'player\',\'original\',\'linked\',\'preview\',\'result\',\'record\')}\\n        if self.phase == \'measure\' and self.measure_context == \'play\':\\n            p = self.play_intent[0]\\n            report = self.quantum_report(p)\\n            data[\'public_measurement\'] = {k:v for k,v in report.items() if k in (\'original\',\'linked\',\'preview\',\'result\')}\\n        if self.phase == \'match_end\': data[\'history\'] = self.history\\n        if self.phase in (\'hand_end\',\'match_end\'): data[\'report\'] = self.history[-1]\\n        return data\\n    def action_hint(self, action):\\n        if action == \'accept\':\\n            if self.pending[\'kind\'] == \'truco\':\\n                return f\\"La mano pasa a valer {self.pending[\'level\']} puntos. Despu\\u00e9s se sigue jugando.\\"\\n            chain = self.pending[\'chain\']\\n            stake = str(15-max(self.scores)) if chain[-1] == \'falta\' else str(envido_value(chain))\\n            measure = \' Se miden las cartas cu\\u00e1nticas que a\\u00fan no se midieron.\' if self.quantum else \'\'\\n            return f\'El ganador suma {stake} puntos.{measure}\'\\n        if action == \'reject\':\\n            pending = self.pending\\n            points = refusal_value(pending[\'chain\']) if pending[\'kind\'] == \'envido\' else pending[\'level\']-1\\n            ending = \'La mano contin\\u00faa.\' if pending[\'kind\'] == \'envido\' else \'La mano termina.\'\\n            if self.scores[pending[\'proposer\']] + points >= 15: ending = \'Llega a 15 y gana la partida.\'\\n            return f\\"{self.names[pending[\'proposer\']]} suma {points} {\'punto\' if points == 1 else \'puntos\'}. {ending}\\"\\n        if action == \'fold\':\\n            return f\\"{self.names[1-self.actor]} suma {self.stake} {\'punto\' if self.stake == 1 else \'puntos\'}. La mano termina.\\"\\n        if action in (\'truco\',\'retruco\',\'vale4\'):\\n            points = {\'truco\':2,\'retruco\':3,\'vale4\':4}[action]\\n            return f\'Si el rival acepta, la mano vale {points} puntos; si rechaza, gan\\u00e1s {points-1}.\'\\n        if action in (\'envido\',\'real\',\'falta\'):\\n            chain = self.pending[\'chain\'] + [action] if self.pending and self.pending[\'kind\'] == \'envido\' else [action]\\n            if action == \'falta\': return f\'Si acepta: {15-max(self.scores)} puntos, lo que le falta a quien va adelante para llegar a 15. Se define con los tantos.\'\\n            return f\'Si acepta: {envido_value(chain)} puntos por los tantos, aparte de la mano.\'\\n        return {\'reassert\':\'El rival debe responder al Truco que qued\\u00f3 pendiente.\',\\n                \'next\':\'Se reparten tres cartas nuevas y cambia el jugador mano.\'}.get(action, \'\')\\n    def private_view(self):\\n        if self.phase not in (\'prepare\',\'play\',\'respond\',\'reassert\'): return {}\\n        p = self.actor\\n        data = {\'player\':p,\'quantum\':self.quantum_report(p)}\\n        if self.phase in (\'prepare\',\'play\',\'respond\',\'reassert\'):\\n            data[\'cards\'] = [{**self.effective_card(p,i).data(),\'index\':i,\'played\':i in self.played[p],\\n                              \'quantum\':self.q[p] is not None and self.q[p].index == i} for i in range(3)]\\n        if self.phase == \'prepare\': data[\'tokens\'] = self.tokens[p]\\n        return data\\n","tutorial":"\\"\\"\\"Interactive Truco tutorial: one scripted match against Bot Q.\\n\\nThe match uses the real game engine in classic mode (no quantum card yet).\\nEach step is one of:\\n  - an explanation (\'title\'/\'text\'), advanced with the \\u00abSiguiente\\u00bb button;\\n  - an explanation with \'expect\': the only game action the player may take;\\n  - a \'bot\' move, executed automatically by the session.\\n\'target\' is a CSS selector the interface highlights.\\n\\"\\"\\"\\n\\nNAMES = (\'Vos\', \'Bot Q\')\\nMANO = 0  # The player starts as mano in the first hand.\\n\\n# Fixed deals: [player cards, Bot Q cards]. Card indices in \'expect\' and \'bot\'\\n# refer to these positions.\\nDEALS = (\\n    # Hand 1 \\u00b7 bazas and card strength. Envido is not used.\\n    (((3, \'espada\'), (5, \'copa\'), (12, \'basto\')),\\n     ((2, \'oro\'), (4, \'copa\'), (11, \'espada\'))),\\n    # Hand 2 \\u00b7 Bot Q is mano and calls Envido (player 33, Bot Q 30); parda.\\n    (((7, \'oro\'), (6, \'oro\'), (4, \'basto\')),\\n     ((3, \'copa\'), (6, \'espada\'), (4, \'espada\'))),\\n    # Hand 3 \\u00b7 Truco and Retruco.\\n    (((1, \'espada\'), (3, \'oro\'), (5, \'basto\')),\\n     ((1, \'basto\'), (12, \'oro\'), (10, \'copa\'))),\\n)\\n\\nSTEPS = (\\n    # ---------- Hand 1 ----------\\n    {\'title\': \'Bienvenido a la mesa\',\\n     \'text\': \'Soy Bot Q. Vamos a jugar tres manos de Truco y te voy a explicar cada parte de \'\\n             \'la pantalla. Le\\u00e9 cada mensaje y toc\\u00e1 \\u00abSiguiente\\u00bb. Cuando haya que jugar, te voy \'\\n             \'a marcar qu\\u00e9 tocar.\',\\n     \'target\': \'.table-scene\'},\\n    {\'title\': \'El marcador\',\\n     \'text\': \'Ac\\u00e1 se anotan los puntos de cada jugador: \\u00ab0 / 15\\u00bb quiere decir 0 puntos de los \'\\n             \'15 necesarios. Gana la partida quien llega primero a 15.\',\\n     \'target\': \'.scoreboard\'},\\n    {\'title\': \'Las cartas del rival\',\\n     \'text\': \'Arriba est\\u00e1n mis tres cartas, boca abajo: no las pod\\u00e9s ver. Cada vez que juego \'\\n             \'una, desaparece de ac\\u00e1 y aparece en el centro de la mesa.\',\\n     \'target\': \'.opponent-hand\'},\\n    {\'title\': \'Tu mano\',\\n     \'text\': \'Abajo est\\u00e1n tus tres cartas: 3 de espada, 5 de copa y 12 de basto. En el Truco \'\\n             \'la fuerza no es el n\\u00famero: el 3 le gana al 12. El orden completo est\\u00e1 en \\u00abValores\\u00bb \'\\n             \'del men\\u00fa de inicio.\',\\n     \'target\': \'.live-hand\'},\\n    {\'title\': \'Las bazas\',\\n     \'text\': \'El centro tiene tres columnas, una por baza. Una baza es una carta de cada \'\\n             \'jugador: gana la carta m\\u00e1s fuerte. Quien gana dos bazas gana la mano.\',\\n     \'target\': \'.played-bazas\'},\\n    {\'title\': \'Qui\\u00e9n es mano y cu\\u00e1nto vale\',\\n     \'text\': \'\\u00abMano: Vos\\u00bb quiere decir que jug\\u00e1s primero y que gan\\u00e1s los empates de Envido. \'\\n             \'Cambia en cada mano. \\u00abTruco: 1\\u00bb es lo que vale ganar esta mano: 1 punto, hasta \'\\n             \'que alguien cante Truco.\',\\n     \'target\': \'.table-status\'},\\n    {\'title\': \'Tus opciones\',\\n     \'text\': \'Estos botones son los cantos: Envido, Real Envido, Falta Envido, Truco e Irse al \'\\n             \'mazo. Debajo de cada uno dice qu\\u00e9 pasa si lo eleg\\u00eds. En esta mano no cantamos: \'\\n             \'solo jugamos cartas.\',\\n     \'target\': \'.actions\'},\\n    {\'title\': \'Jug\\u00e1 tu primera carta\',\\n     \'text\': \'Toc\\u00e1 tu 3 de espada (o arrastralo al centro). Su fuerza es 10 de 14.\',\\n     \'target\': \'[data-card=\\"0\\"]\', \'expect\': [\'play\', 0]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Ganaste la primera baza\',\\n     \'text\': \'Yo jugu\\u00e9 un 2 de oro (fuerza 9) y tu 3 (fuerza 10) es m\\u00e1s fuerte. Cada vez que \'\\n             \'termina una baza aparece un aviso: avanzalo con \\u00abSkip \\u00b7 Continuar\\u00bb o eleg\\u00ed un \'\\n             \'tiempo con \\u23f1. Quien gana la baza empieza la siguiente.\',\\n     \'target\': \'.played-bazas\'},\\n    {\'title\': \'Segunda baza\',\\n     \'text\': \'Jug\\u00e1 tu 12 de basto (fuerza 7). Si gan\\u00e1s esta baza, ya ten\\u00e9s dos de tres.\',\\n     \'target\': \'[data-card=\\"2\\"]\', \'expect\': [\'play\', 2]},\\n    {\'bot\': [\'play\', 2]},\\n    {\'title\': \'Ganaste la mano\',\\n     \'text\': \'Tu 12 le gan\\u00f3 a mi 11. Con dos bazas ganadas la mano es tuya y, sin cantos, vale \'\\n             \'1 punto. \\u00abVer resumen\\u00bb muestra por qu\\u00e9 se gan\\u00f3 cada baza. Toc\\u00e1 \\u00abNueva mano\\u00bb para \'\\n             \'repartir otra vez.\',\\n     \'target\': \'[data-action=\\"next\\"]\', \'expect\': [\'next\', None]},\\n\\n    # ---------- Hand 2 ----------\\n    {\'bot\': [\'envido\', None]},\\n    {\'title\': \'Ahora soy mano\',\\n     \'text\': \'En cada mano cambia qui\\u00e9n es mano: ahora juego primero yo. Antes de tirar mi \'\\n             \'carta cant\\u00e9 Envido. El Envido solo se puede cantar antes de jugar tu primera carta.\',\\n     \'target\': \'.table-status\'},\\n    {\'title\': \'C\\u00f3mo se cuentan los tantos\',\\n     \'text\': \'Si ten\\u00e9s dos cartas del mismo palo, sum\\u00e1s 20 m\\u00e1s el valor de cada una. Del 1 al 7 \'\\n             \'valen su n\\u00famero; el 10, 11 y 12 valen 0. Tu 7 y 6 de oro dan 20 + 7 + 6 = 33. \'\\n             \'Son muy buenos tantos.\',\\n     \'target\': \'.live-hand\'},\\n    {\'title\': \'Respond\\u00e9 al Envido\',\\n     \'text\': \'Toc\\u00e1 \\u00abQuiero\\u00bb: comparamos tantos y el que tiene m\\u00e1s suma 2 puntos. \\u00abNo quiero\\u00bb me \'\\n             \'dar\\u00eda 1 punto sin comparar. Real Envido y Falta Envido suben la apuesta.\',\\n     \'target\': \'[data-action=\\"accept\\"]\', \'expect\': [\'accept\', None]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Ganaste el Envido\',\\n     \'text\': \'Tus 33 le ganan a mis 30: sumaste 2 puntos en el marcador. Los puntos del Envido \'\\n             \'son aparte de la mano, que se sigue jugando. Despu\\u00e9s tir\\u00e9 mi 3 de copa.\',\\n     \'target\': \'.scoreboard\'},\\n    {\'title\': \'Ganale a mi 3\',\\n     \'text\': \'Mi 3 de copa tiene fuerza 10. Tu 7 de oro es la cuarta carta m\\u00e1s fuerte del juego \'\\n             \'(fuerza 11). Jugalo.\',\\n     \'target\': \'[data-card=\\"0\\"]\', \'expect\': [\'play\', 0]},\\n    {\'title\': \'Empez\\u00e1s vos\',\\n     \'text\': \'Ganaste la baza, as\\u00ed que abr\\u00eds la segunda. Jug\\u00e1 tu 6 de oro.\',\\n     \'target\': \'[data-card=\\"1\\"]\', \'expect\': [\'play\', 1]},\\n    {\'bot\': [\'play\', 1]},\\n    {\'title\': \'Baza parda\',\\n     \'text\': \'Los dos jugamos un 6: misma fuerza, la baza es \\u00abparda\\u00bb (empate). Si la primera \'\\n             \'baza tiene ganador y la segunda es parda, gana la mano quien gan\\u00f3 la primera. \'\\n             \'Sum\\u00e1s 1 punto m\\u00e1s. Toc\\u00e1 \\u00abNueva mano\\u00bb.\',\\n     \'target\': \'[data-action=\\"next\\"]\', \'expect\': [\'next\', None]},\\n\\n    # ---------- Hand 3 ----------\\n    {\'title\': \'Tercera mano: el Truco\',\\n     \'text\': \'Volv\\u00e9s a ser mano. Ten\\u00e9s el 1 de espada, el \\u00abancho de espada\\u00bb: la carta m\\u00e1s \'\\n             \'fuerte del juego (fuerza 14). Con buenas cartas conviene cantar Truco.\',\\n     \'target\': \'.live-hand\'},\\n    {\'title\': \'Cant\\u00e1 Truco\',\\n     \'text\': \'Toc\\u00e1 \\u00abTruco\\u00bb. Si quiero, la mano pasa a valer 2 puntos. Si no quiero, gan\\u00e1s 1 \'\\n             \'punto y la mano termina.\',\\n     \'target\': \'[data-action=\\"truco\\"]\', \'expect\': [\'truco\', None]},\\n    {\'bot\': [\'accept\', None]},\\n    {\'title\': \'Dije \\u00abQuiero\\u00bb\',\\n     \'text\': \'Ahora la mano vale 2: mir\\u00e1 \\u00abTruco: 2\\u00bb. Quien acepta un canto gana el derecho a \'\\n             \'subirlo: yo puedo cantar Retruco (3) y vos, despu\\u00e9s, Vale Cuatro (4).\',\\n     \'target\': \'.table-status\'},\\n    {\'title\': \'Guard\\u00e1 las cartas fuertes\',\\n     \'text\': \'Empez\\u00e1 con tu carta m\\u00e1s baja, el 5 de basto. As\\u00ed guard\\u00e1s el ancho y el 3 para las \'\\n             \'bazas siguientes.\',\\n     \'target\': \'[data-card=\\"2\\"]\', \'expect\': [\'play\', 2]},\\n    {\'bot\': [\'play\', 2]},\\n    {\'bot\': [\'retruco\', None]},\\n    {\'title\': \'Perdiste una baza y cant\\u00e9 Retruco\',\\n     \'text\': \'Mi 10 de copa (fuerza 5) le gan\\u00f3 a tu 5 (fuerza 2), as\\u00ed que abro la segunda baza. \'\\n             \'Antes de jugar cant\\u00e9 Retruco: si quer\\u00e9s, la mano vale 3.\',\\n     \'target\': \'.played-bazas\'},\\n    {\'title\': \'Acept\\u00e1 el Retruco\',\\n     \'text\': \'Toc\\u00e1 \\u00abQuiero\\u00bb. \\u00abNo quiero\\u00bb me dar\\u00eda los 2 puntos del Truco ya aceptado y \'\\n             \'terminar\\u00eda la mano. \\u00abVale Cuatro\\u00bb subir\\u00eda la apuesta a 4.\',\\n     \'target\': \'[data-action=\\"accept\\"]\', \'expect\': [\'accept\', None]},\\n    {\'bot\': [\'play\', 0]},\\n    {\'title\': \'Jug\\u00e1 el ancho de espada\',\\n     \'text\': \'Tir\\u00e9 el 1 de basto, el \\u00abancho de basto\\u00bb (fuerza 13). Solo pierde contra tu 1 de \'\\n             \'espada. Jugalo.\',\\n     \'target\': \'[data-card=\\"0\\"]\', \'expect\': [\'play\', 0]},\\n    {\'title\': \'\\u00daltima baza\',\\n     \'text\': \'Vamos una baza cada uno. Jug\\u00e1 tu 3 de oro (fuerza 10).\',\\n     \'target\': \'[data-card=\\"1\\"]\', \'expect\': [\'play\', 1]},\\n    {\'bot\': [\'play\', 1]},\\n    {\'title\': \'\\u00a1Terminaste el tutorial!\',\\n     \'text\': \'Tu 3 le gan\\u00f3 a mi 12 y te llevaste la mano con Retruco: 3 puntos. Ya sab\\u00e9s leer \'\\n             \'la mesa, jugar bazas, cantar y responder Envido y Truco. Una partida real sigue \'\\n             \'hasta 15 puntos. Lo pr\\u00f3ximo: la carta cu\\u00e1ntica.\',\\n     \'target\': \'.outcome\', \'final\': True},\\n)\\n","service":"\\"\\"\\"Session API shared by local HTTP and Qollab Python imports.\\"\\"\\"\\nimport json\\nimport platform\\nimport qiskit\\nfrom .game import Game\\nfrom .quantum import LocalSampler\\nfrom .remote import RemoteMeasurement\\nfrom . import tutorial\\n\\nclass Session:\\n    def __init__(self, local=False):\\n        self.local = local\\n        self.host_local = local\\n        self.game = None\\n        self.remote = None\\n        self.guided = False  # True while the scripted tutorial match is active.\\n        self.coach = 0  # Index of the current tutorial step.\\n        self.error = None\\n        self.errors = []\\n    def output(self, private=False):\\n        result = {\'mode\':LocalSampler.name if self.local else \'Qollab \\u00b7 IonQ injected backend \\u00b7 one-job limit\',\\n                  \'development_mode\':self.local, \'host_local\':self.host_local,\\n                  \'versions\':{\'python\':platform.python_version(),\'qiskit\':qiskit.__version__},\\n                  \'error\':self.error,\'guided\':self.guided, \'remote_info\':self.remote.info() if self.remote else None,\\n                  \'remote_error\':self.remote.last_error if self.remote else None}\\n        if self.game:\\n            result[\'game\'] = self.game.public_view()\\n            if private: result[\'private\'] = self.game.private_view()\\n        if self.guided: result[\'coach\'] = self.coach_view()\\n        return result\\n    def coach_view(self):\\n        explained = [i for i, s in enumerate(tutorial.STEPS) if \'bot\' not in s]\\n        step = tutorial.STEPS[self.coach]\\n        return {\'title\':step[\'title\'], \'text\':step[\'text\'], \'target\':step.get(\'target\'),\\n                \'expect\':step.get(\'expect\'), \'final\':step.get(\'final\', False),\\n                \'step\':explained.index(self.coach)+1, \'total\':len(explained)}\\n    def advance(self):\\n        \\"\\"\\"Move past the current step and play Bot Q\'s scripted moves.\\"\\"\\"\\n        self.coach += 1\\n        while self.coach < len(tutorial.STEPS) and \'bot\' in tutorial.STEPS[self.coach]:\\n            action, value = tutorial.STEPS[self.coach][\'bot\']\\n            if self.game.actor != 1: raise RuntimeError(\'Guion del tutorial desincronizado\')\\n            self.game.dispatch(action, value)\\n            self.coach += 1\\n    def tutorial_action(self, action, value):\\n        step = tutorial.STEPS[self.coach]\\n        if action == \'coach_next\':\\n            if step.get(\'expect\') or step.get(\'final\'): raise ValueError(\'Segu\\u00ed la indicaci\\u00f3n de Bot Q para continuar.\')\\n            self.advance()\\n            return\\n        if step.get(\'expect\') != [action, value]:\\n            raise ValueError(\'En el tutorial, segu\\u00ed la indicaci\\u00f3n de Bot Q: \' + step[\'title\'] + \'.\')\\n        self.game.dispatch(action, value)\\n        self.advance()\\n    def action(self, payload):\\n        self.error = None\\n        action = payload[\'action\']; value = payload.get(\'value\')\\n        if action in (\'new\',\'tutorial\') and self.needs_measurement():\\n            raise ValueError(\'Hay una medici\\u00f3n pendiente. Completala o consult\\u00e1 su resultado antes de cambiar de partida o lecci\\u00f3n.\')\\n        if action == \'dev_mode\':\\n            if type(value) is not bool: raise ValueError(\'Modo inv\\u00e1lido\')\\n            if self.host_local and not value: raise ValueError(\'El servidor local solo admite modo de desarrollo\')\\n            if value != self.local and self.remote and self.remote.started is not None:\\n                raise ValueError(\'Consult\\u00e1 el resultado IonQ pendiente antes de cambiar el modo de medici\\u00f3n.\')\\n            self.local = value\\n        elif action == \'new\':\\n            if isinstance(value,dict) and value.get(\'noise\',False) and not self.local:\\n                raise ValueError(\'El ruido educativo requiere simulaci\\u00f3n local con Qiskit; no se agrega a IonQ.\')\\n            game = Game(value.get(\'names\'), privacy=value.get(\'privacy\', False), noise=value.get(\'noise\',False)) if isinstance(value, dict) else Game(value)\\n            self.guided = False\\n            self.game = game\\n        elif action == \'tutorial\':\\n            # Classic Truco against scripted Bot Q; the quantum card is not used yet.\\n            self.game = Game(list(tutorial.NAMES), quantum=False, deals=tutorial.DEALS, mano=tutorial.MANO)\\n            self.guided = True\\n            self.coach = -1\\n            self.advance()\\n        elif action == \'noise_tick\':\\n            if not self.local or not self.game or not self.game.noise:\\n                raise ValueError(\'El ruido educativo no est\\u00e1 activo\')\\n            g=self.game\\n            if not isinstance(value,dict) or type(value.get(\'hand\')) is not int or type(value.get(\'player\')) is not int or value.get(\'hand\') != g.hand_number or value.get(\'player\') != g.actor or g.phase not in (\'play\',\'respond\',\'reassert\'):\\n                raise ValueError(\'El turno del ruido cambi\\u00f3\')\\n            g.q[g.actor].age(value.get(\'seconds\'))\\n            return self.output(private=True)\\n        elif action == \'reveal\': return self.output(private=True)\\n        elif action == \'public\': return self.output()\\n        else:\\n            if self.game is None: raise ValueError(\'Inici\\u00e1 una partida\')\\n            if self.guided: self.tutorial_action(action, value)\\n            else: self.game.dispatch(action,value)\\n        return self.output(private=action in (\'choose\',\'edit\'))\\n    def needs_measurement(self):\\n        return self.game is not None and self.game.phase==\'measure\'\\n    def sequences(self):\\n        return [self.game.q[p].gates for p in self.game.measure_requests]\\n    def accept_measurements(self, measurements):\\n        self.game.complete_measure(measurements)\\n    def start(self, backend=None):\\n        if not self.needs_measurement(): return self.output()\\n        if self.local:\\n            sampler = LocalSampler()\\n            times = [self.game.q[p].noise_seconds if self.game.noise else None for p in self.game.measure_requests]\\n            self.accept_measurements([sampler.sample(gates, seconds) for gates,seconds in zip(self.sequences(),times)])\\n            return self.output()\\n        if self.game.noise:\\n            raise ValueError(\'Esta partida usa ruido educativo local. Eleg\\u00ed simulaci\\u00f3n local para medirla; no se env\\u00eda a IonQ.\')\\n        if self.remote is None: self.remote = RemoteMeasurement(backend)\\n        self.remote.start(self.sequences())\\n        return self.output()\\n    def poll(self):\\n        if self.local: return {\'done\':True,\'view\':self.output()}\\n        response = self.remote.poll()\\n        if response[\'done\']:\\n            self.accept_measurements(response[\'measurements\'])\\n            self.remote.release()\\n        return {\'done\':response[\'done\'],\'view\':self.output()}\\n    def safe(self, fn):\\n        self.error = None\\n        try: return fn()\\n        except (ValueError,RuntimeError,TimeoutError) as exc:\\n            self.error = str(exc)\\n            self.errors.append({\'type\':type(exc).__name__,\'message\':self.error})\\n            return self.output()\\n        except Exception as exc:\\n            # Do not return arbitrary provider errors which can contain credentials.\\n            self.error = f\'Fall\\u00f3 la operaci\\u00f3n ({type(exc).__name__}). No se gener\\u00f3 un resultado.\'\\n            self.errors.append({\'type\':type(exc).__name__})\\n            return self.output()\\n\\n# In Qollab the Python module is imported once per run; all state stays in memory.\\n_session = Session()\\n\\ndef dispatch_json(payload):\\n    return json.dumps(_session.safe(lambda:_session.action(json.loads(payload))))\\n\\ndef start_json(backend):\\n    return json.dumps(_session.safe(lambda:_session.start(backend)))\\n\\ndef poll_json():\\n    return json.dumps(_session.safe(_session.poll))\\n\\n\\ndef demo_json():\\n    import base64\\n    # Source checkouts keep artifacts/; Qollab\'s flat upload keeps root files.\\n    for prefix in (\'artifacts/\', \'\'):\\n        try:\\n            with open(prefix + \'truco-cuantico-demo.mp4\', \'rb\') as f:\\n                data = base64.b64encode(f.read()).decode(\'ascii\')\\n            with open(prefix + \'DEMO_TRANSCRIPT.txt\', encoding=\'utf8\') as f:\\n                transcript = f.read()\\n            return json.dumps({\'data\':data,\'transcript\':transcript})\\n        except OSError:\\n            continue\\n    return json.dumps({\'error\':\'Video no disponible en este paquete. Consult\\u00e1 DEMO_SCRIPT.md.\'})\\n"}')
_SERVICE = None


def _service():
    global _SERVICE
    if _SERVICE is None:
        root = '_qriollo_qollab'
        package = types.ModuleType(root)
        package.__path__ = []
        package.__package__ = root
        sys.modules[root] = package
        exec(compile(_SOURCES['__init__'], '<qollab_engine/__init__.py>', 'exec'), package.__dict__)
        for name in ('gates', 'classic', 'quantum', 'remote', 'game', 'tutorial', 'service'):
            module = types.ModuleType(root + '.' + name)
            module.__package__ = root
            module.__file__ = '<qollab_engine/' + name + '.py>'
            sys.modules[module.__name__] = module
            setattr(package, name, module)
            exec(compile(_SOURCES[name], module.__file__, 'exec'), module.__dict__)
        _SERVICE = sys.modules[root + '.service']
    return _SERVICE


def dispatch_json(payload):
    return _service().dispatch_json(payload)


def start_json(backend):
    return _service().start_json(backend)


def poll_json():
    return _service().poll_json()


def demo_json():
    return _service().demo_json()
